def preencher_rotulos_precos(apps, schema_editor):
    ProdutoPreco = apps.get_model("produtos", "ProdutoPreco")
    for preco in ProdutoPreco.objects.all():
        if preco.rotulo:
            continue
        if preco.duracao_minutos is not None:
            preco.rotulo = DURACAO_LABELS.get(
                preco.duracao_minutos, str(preco.duracao_minutos)
            )
        else:
            preco.rotulo = f"opcao-{preco.pk}"
        preco.save(update_fields=["rotulo"])


